// src/hooks/useApi.js - хук для работы с API
import { useState, useEffect, useCallback } from 'react'; // 🚀 Добавлен useCallback

const useApi = (url) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // 🚀 Унифицированная и надежная функция для выполнения запроса
  const fetchData = useCallback(async (isRefetch = false) => {
    // При refetch не показываем лоадер, если данные уже есть, для лучшего UX
    if (!isRefetch || data === null) {
      setLoading(true);
    }
    setError(null);

    try {
      const response = await fetch(url);

      // ✅ Проверка на HTTP-ошибки (404, 500 и т.д.)
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status} (${response.statusText || 'Unknown'})`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      // ✅ Ловит NetworkError, CORS и ошибки парсинга JSON
      setError(err.message || 'Unknown API Error');
      setData(null); // Сбрасываем данные при ошибке
    } finally {
      setLoading(false);
    }
  }, [url]);

  useEffect(() => {
    if (url) {
      fetchData();
    }
    // В зависимости добавлен fetchData, чтобы useEffect мог его использовать.
  }, [url, fetchData]); 

  const refetch = () => {
    if (url) {
      // 🚀 Используем основную логику запроса для refetch
      fetchData(true); 
    }
  };

  return { data, loading, error, refetch };
};

export default useApi;
